function normalizeKingdomPlayerCount(value, fallback = PLAYERS.length) {
  return Math.max(3, Math.min(PLAYERS.length, Math.floor(Number(value) || fallback)));
}

function getKingdomPlayerCount(state = s) {
  if (Array.isArray(state?.players) && state.players.length >= 3) {
    return normalizeKingdomPlayerCount(state.players.length);
  }
  return normalizeKingdomPlayerCount(state?.rules?.playerCount);
}

function getKingdomSeatIndexes(state = s) {
  return Array.from({ length: getKingdomPlayerCount(state) }, (_, index) => index);
}

function getKingdomSeatClaimOrder(hasReservedHostPet = false) {
  return hasReservedHostPet ? [0, 2, 3, 1] : [0, 1, 2, 3];
}

function getKingdomPetDisplayName(pet, fallback = 'ペット') {
  return String(
    pet?.displayName
    || pet?.nickname
    || pet?.monsterName
    || pet?.monsterId
    || fallback
  ).trim() || fallback;
}

function buildKingdomPetPlayerTemplate(pet, owner = {}) {
  if (!pet?.monsterId) return null;
  const ownerPlayFabId = String(owner?.playFabId || owner?.uid || '').trim();
  const ownerSeat = Number(owner?.seat);
  return {
    id: ownerPlayFabId ? `pet-${ownerPlayFabId}` : 'pet',
    name: getKingdomPetDisplayName(pet),
    isNpc: true,
    isPet: true,
    pet: { ...pet },
    petOwnerPlayFabId: ownerPlayFabId,
    petOwnerUid: String(owner?.uid || ownerPlayFabId).trim(),
    petOwnerSeat: Number.isInteger(ownerSeat) ? ownerSeat : null
  };
}

function getKingdomPresencePet(info) {
  const pet = info?.currentPet;
  return pet && typeof pet === 'object' && String(pet.monsterId || '').trim()
    ? cloneKingdomSnapshotValue(pet, null)
    : null;
}

function buildKingdomOnlinePetSeatAssignments(seatTaken = []) {
  const humanSeats = new Set();
  seatTaken.forEach((occupant, seat) => {
    if (occupant) humanSeats.add(seat);
  });
  const assignments = new Map();
  seatTaken.forEach((occupant, ownerSeat) => {
    const pet = getKingdomPresencePet(occupant);
    const petSeat = ownerSeat + 1;
    if (
      !pet
      || petSeat >= PLAYERS.length
      || humanSeats.has(petSeat)
      || assignments.has(petSeat)
    ) return;
    const template = buildKingdomPetPlayerTemplate(pet, {
      seat: ownerSeat,
      uid: occupant.uid,
      playFabId: occupant.playFabId || occupant.uid
    });
    if (template) assignments.set(petSeat, template);
  });
  return assignments;
}

function getKingdomReservedPetSeatsFromPresence(presence = {}) {
  const seatTaken = Array.from({ length: PLAYERS.length }, () => null);
  Object.entries(presence && typeof presence === 'object' ? presence : {}).forEach(([uid, info]) => {
    if (!isFreshKingdomPresence(info)) return;
    const seat = Number(info?.seat);
    if (!Number.isInteger(seat) || seat < 0 || seat >= PLAYERS.length) return;
    seatTaken[seat] = { uid, ...info };
  });
  return new Set(buildKingdomOnlinePetSeatAssignments(seatTaken).keys());
}

function buildKingdomOnlinePresenceRosterPreview(presenceRows = []) {
  const seatTaken = Array.from({ length: PLAYERS.length }, () => null);
  (Array.isArray(presenceRows) ? presenceRows : []).forEach((entry) => {
    const seat = Number(entry?.seat);
    if (!Number.isInteger(seat) || seat < 0 || seat >= PLAYERS.length) return;
    seatTaken[seat] = {
      uid: String(entry?.uid || entry?.playFabId || `preview-${seat}`),
      playFabId: String(entry?.playFabId || entry?.uid || `preview-${seat}`),
      displayName: String(entry?.displayName || entry?.name || `Player${seat + 1}`),
      currentPet: entry?.currentPet && typeof entry.currentPet === 'object'
        ? cloneKingdomSnapshotValue(entry.currentPet, null)
        : null
    };
  });
  const pets = buildKingdomOnlinePetSeatAssignments(seatTaken);
  return seatTaken.map((occupant, seat) => {
    if (occupant) {
      return {
        seat,
        kind: 'player',
        name: occupant.displayName,
        playFabId: occupant.playFabId
      };
    }
    const pet = pets.get(seat);
    if (pet) {
      return {
        seat,
        kind: 'pet',
        name: pet.name,
        ownerPlayFabId: pet.petOwnerPlayFabId,
        monsterId: pet.pet?.monsterId || ''
      };
    }
    return { seat, kind: 'npc', name: `NPC${seat}` };
  });
}

function getKingdomInitialPlayerTemplates() {
  const context = kingdomExplorationSession?.context || null;
  const petTemplate = buildKingdomPetPlayerTemplate(
    context?.currentPet && typeof context.currentPet === 'object' ? context.currentPet : null
  );
  if (context?.mode === 'online') {
    const roster = PLAYERS.map((player) => ({ ...player }));
    if (petTemplate) roster[1] = petTemplate;
    return roster;
  }
  if (context?.mode !== 'offline') return PLAYERS;
  const roster = PLAYERS.slice(0, 3).map((player) => ({ ...player }));
  if (petTemplate) roster.splice(1, 0, petTemplate);
  return roster;
}

function getKingdomMercenaryOrdinal(players, playerIndex) {
  const list = Array.isArray(players) ? players : [];
  let ordinal = 0;
  for (let index = 0; index <= playerIndex && index < list.length; index += 1) {
    const player = list[index];
    if (index !== getLocalPlayerIndex() && player?.isPet !== true) ordinal += 1;
  }
  return Math.max(1, ordinal);
}

const NPC_POLICY_VARIANCE = Object.freeze({
  tempo: 0.07,
  preserve: 0.08,
  control: 0.06,
  commit: 0.06
});
const NPC_NEAR_OPTIMAL_MIN_GAP = 8;
const NPC_NEAR_OPTIMAL_RATE = 0.03;
const NPC_FORCED_WIN_SCORE = 1000000;

function hashKingdomNpcPolicySeed(value) {
  const text = String(value ?? '');
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  hash >>>= 0;
  return hash || 0x6d2b79f5;
}

function mixKingdomNpcPolicySeed(seed, salt = 0) {
  let value = (Number(seed) >>> 0) ^ (Number(salt) >>> 0);
  value = Math.imul(value ^ (value >>> 16), 0x7feb352d);
  value = Math.imul(value ^ (value >>> 15), 0x846ca68b);
  value = (value ^ (value >>> 16)) >>> 0;
  return value || 0x6d2b79f5;
}

function createKingdomNpcPolicySeed(player, playerIndex, randomSource = kingdomNpcRandom) {
  const sample = Math.max(0, Math.min(0.999999999, Number(randomSource?.()) || 0));
  const randomBits = Math.floor(sample * 0x100000000) >>> 0;
  const identityBits = hashKingdomNpcPolicySeed(`${player?.id || player?.name || 'npc'}:${playerIndex}`);
  return mixKingdomNpcPolicySeed(randomBits ^ identityBits, 0x9e3779b9 + Number(playerIndex || 0));
}

function normalizeKingdomNpcPolicySeed(value, player, playerIndex, fallbackSalt = '') {
  const numeric = Number(value);
  if (Number.isFinite(numeric) && (numeric >>> 0) !== 0) return numeric >>> 0;
  return mixKingdomNpcPolicySeed(
    hashKingdomNpcPolicySeed(`${fallbackSalt}:${player?.id || player?.name || 'npc'}:${playerIndex}`),
    0x85ebca6b
  );
}

function getKingdomNpcPolicyUnit(seed, salt) {
  return mixKingdomNpcPolicySeed(seed, salt) / 0x100000000;
}

function ensureKingdomNpcDecisionState(targetState = s, randomSource = kingdomNpcRandom) {
  if (!targetState || !Array.isArray(targetState.players)) return;
  const incomingSeeds = Array.isArray(targetState.npcPolicySeeds) ? targetState.npcPolicySeeds : [];
  targetState.npcPolicySeeds = targetState.players.map((player, playerIndex) => {
    if (player?.isNpc !== true) return 0;
    const current = Number(incomingSeeds[playerIndex]) >>> 0;
    return current || createKingdomNpcPolicySeed(player, playerIndex, randomSource);
  });
  const incomingPassCounts = Array.isArray(targetState.npcPassCounts) ? targetState.npcPassCounts : [];
  targetState.npcPassCounts = targetState.players.map((_, playerIndex) => (
    Math.max(0, Math.min(8, Math.floor(Number(incomingPassCounts[playerIndex]) || 0)))
  ));
}

function getKingdomNpcPolicy(playerIndex) {
  ensureKingdomNpcDecisionState();
  const seed = Number(s?.npcPolicySeeds?.[playerIndex]) >>> 0;
  const factor = (salt, variance) => 1 + ((getKingdomNpcPolicyUnit(seed, salt) * 2 - 1) * variance);
  return {
    seed,
    tempo: factor(0x13579bdf, NPC_POLICY_VARIANCE.tempo),
    preserve: factor(0x2468ace0, NPC_POLICY_VARIANCE.preserve),
    control: factor(0x1b873593, NPC_POLICY_VARIANCE.control),
    commit: factor(0x5bd1e995, NPC_POLICY_VARIANCE.commit)
  };
}

function resetKingdomNpcPassCounts(playerIndex = null) {
  if (!s?.players) return;
  if (!Array.isArray(s.npcPassCounts) || s.npcPassCounts.length !== s.players.length) {
    s.npcPassCounts = s.players.map(() => 0);
  }
  if (Number.isInteger(playerIndex) && playerIndex >= 0 && playerIndex < s.npcPassCounts.length) {
    s.npcPassCounts[playerIndex] = 0;
    return;
  }
  s.npcPassCounts = s.players.map(() => 0);
}

