function clearKingdomTrickSceneFlash(shouldRender = false) {
  if (kingdomTrickSceneFlashTimer) {
    clearTimeout(kingdomTrickSceneFlashTimer);
    kingdomTrickSceneFlashTimer = null;
  }
  kingdomTrickSceneFlashKind = '';
  if (shouldRender) render();
}

function playKingdomTrickSceneFlashLocal(kind, durationMs = 780) {
  if (!kind) return;
  if (!['cut', 'skip'].includes(String(kind))) return;
  kingdomTrickSceneFlashKind = String(kind);
  if (kingdomTrickSceneFlashTimer) {
    clearTimeout(kingdomTrickSceneFlashTimer);
    kingdomTrickSceneFlashTimer = null;
  }
  const holdMs = Math.max(220, Number(durationMs) || 0);
  kingdomTrickSceneFlashTimer = setTimeout(() => {
    kingdomTrickSceneFlashTimer = null;
    kingdomTrickSceneFlashKind = '';
    render();
  }, holdMs);
  render();
}

function triggerKingdomTrickSceneFlash(kind, durationMs = 780, options = {}) {
  let cue = null;
  if (options?.sync !== false) {
    cue = enqueueKingdomPresentationCue('field-flash', {
      variant: String(kind || ''),
      durationMs
    });
  }
  if (cue) markKingdomPresentationCuePlayed(s?.presentation?.epoch, cue.seq);
  playKingdomTrickSceneFlashLocal(kind, durationMs);
}

function preloadKingdomFieldScenes() {
  if (kingdomFieldScenePreloadStarted || typeof Image !== 'function') return;
  kingdomFieldScenePreloadStarted = true;
  const loadNext = (index = 0) => {
    if (index >= KINGDOM_FIELD_SCENE_SRCS.length) return;
    const run = async () => {
      const image = new Image();
      image.decoding = 'async';
      image.src = KINGDOM_FIELD_SCENE_SRCS[index];
      try {
        if (typeof image.decode === 'function') await image.decode();
      } catch {
        // The active scene retries through the normal browser cache.
      }
      loadNext(index + 1);
    };
    if (typeof requestIdleCallback === 'function') {
      requestIdleCallback(() => { void run(); }, { timeout: 1200 });
    } else {
      setTimeout(() => { void run(); }, 24);
    }
  };
  loadNext();
}

function clearKingdomFieldSceneTransition({ reset = false } = {}) {
  if (kingdomFieldSceneFrame) {
    cancelAnimationFrame(kingdomFieldSceneFrame);
    kingdomFieldSceneFrame = 0;
  }
  if (kingdomFieldSceneCleanupTimer) {
    clearTimeout(kingdomFieldSceneCleanupTimer);
    kingdomFieldSceneCleanupTimer = null;
  }
  if (!reset) return;
  kingdomFieldSceneSignature = '';
  kingdomFieldSceneLayerIndex = 0;
}

function ensureKingdomFieldSceneLayers() {
  if (!ui.trick) return [];
  let layers = Array.from(ui.trick.querySelectorAll(':scope > .tarot-kingdom-field-scene-layer'));
  while (layers.length < 2) {
    const layer = document.createElement('span');
    layer.className = 'tarot-kingdom-field-scene-layer';
    layer.setAttribute('aria-hidden', 'true');
    ui.trick.insertBefore(layer, ui.trick.firstChild);
    layers = Array.from(ui.trick.querySelectorAll(':scope > .tarot-kingdom-field-scene-layer'));
  }
  return layers.slice(0, 2);
}

function syncKingdomFieldSceneFade() {
  if (!ui.trick || typeof getComputedStyle !== 'function') return;
  const layers = ensureKingdomFieldSceneLayers();
  if (layers.length < 2) return;
  const style = getComputedStyle(ui.trick);
  const roleSuitTint = style.getPropertyValue('--kingdom-role-suit-tint').trim() || 'transparent';
  const tint = style.getPropertyValue('--kingdom-field-tint').trim()
    .replaceAll('var(--kingdom-role-suit-tint)', roleSuitTint);
  const shade = style.getPropertyValue('--kingdom-field-shade').trim();
  const scene = style.getPropertyValue('--kingdom-field-scene').trim();
  const position = style.getPropertyValue('--kingdom-field-position').trim() || 'center, center, center';
  const size = style.getPropertyValue('--kingdom-field-size').trim() || '100% 100%, 100% 100%, cover';
  const backgroundImage = [tint, shade, scene].filter(Boolean).join(', ');
  const signature = `${backgroundImage}|${position}|${size}`;
  const currentLayer = layers[kingdomFieldSceneLayerIndex] || layers[0];
  if (!kingdomFieldSceneSignature || !currentLayer.style.backgroundImage) {
    clearKingdomFieldSceneTransition();
    layers.forEach((layer) => layer.classList.remove('is-active'));
    currentLayer.style.backgroundImage = backgroundImage;
    currentLayer.style.backgroundPosition = position;
    currentLayer.style.backgroundSize = size;
    currentLayer.classList.add('is-active');
    kingdomFieldSceneSignature = signature;
    return;
  }
  if (signature === kingdomFieldSceneSignature) return;

  clearKingdomFieldSceneTransition();
  const previousLayer = currentLayer;
  const nextIndex = kingdomFieldSceneLayerIndex === 0 ? 1 : 0;
  const nextLayer = layers[nextIndex];
  const showImmediately = ui.trick.classList.contains('is-scene-cut');
  nextLayer.classList.remove('is-active');
  nextLayer.style.backgroundImage = backgroundImage;
  nextLayer.style.backgroundPosition = position;
  nextLayer.style.backgroundSize = size;
  kingdomFieldSceneSignature = signature;
  kingdomFieldSceneLayerIndex = nextIndex;
  if (showImmediately) {
    previousLayer.classList.remove('is-active');
    nextLayer.classList.add('is-active');
    previousLayer.style.backgroundImage = '';
    previousLayer.style.backgroundPosition = '';
    previousLayer.style.backgroundSize = '';
    return;
  }
  void nextLayer.offsetWidth;
  kingdomFieldSceneFrame = requestAnimationFrame(() => {
    kingdomFieldSceneFrame = 0;
    previousLayer.classList.remove('is-active');
    nextLayer.classList.add('is-active');
    kingdomFieldSceneCleanupTimer = setTimeout(() => {
      kingdomFieldSceneCleanupTimer = null;
      previousLayer.style.backgroundImage = '';
      previousLayer.style.backgroundPosition = '';
      previousLayer.style.backgroundSize = '';
    }, 460);
  });
}

function getKingdomTrickRoleSuit(play) {
  const roleKey = String(play?.role?.key || '');
  if (!['Flush', 'StraightFlush'].includes(roleKey)) return '';
  const cards = Array.isArray(play?.cardsTable) ? play.cardsTable : [];
  return SUITS.find((suit) => (
    cards.length === 5
    && cards.every((card) => suitsForCard(card, true).includes(suit))
  )) || '';
}

function syncKingdomTrickSceneClass() {
  if (!ui.trick) return;
  const roleChain = getKingdomRoleChain(s?.trick);
  const visibleChainCount = String(s?.trick?.type || '') === 'role' && roleChain.count >= 2
    ? roleChain.count
    : 0;
  ui.trick.dataset.roleChain = visibleChainCount ? String(visibleChainCount) : '';
  ui.trick.style.setProperty('--role-chain-level', String(Math.min(3, Math.max(0, roleChain.count - 1))));
  try {
    ui.trick.classList.remove(...KINGDOM_TRICK_SCENE_CLASSES);
    if (window.__TAROT_KINGDOM_PREVIEW__ === true && kingdomDemoTrickSceneKey !== 'auto') {
      const demoScene = KINGDOM_DEMO_TRICK_SCENE_OPTIONS.find(
        (option) => option.value === kingdomDemoTrickSceneKey
      );
      if (demoScene) {
        if (demoScene.classes.length) ui.trick.classList.add(...demoScene.classes);
        return;
      }
    }
    const roleKey = String(s?.trick?.role?.key || '');
    const roleSceneClass = String(s?.trick?.type || '') === 'role'
      ? KINGDOM_TRICK_ROLE_SCENE_CLASSES[roleKey] || ''
      : '';
    if (roleSceneClass) {
      ui.trick.classList.add('is-scene-role', roleSceneClass);
      const roleSuit = getKingdomTrickRoleSuit(s.trick);
      if (roleSuit) ui.trick.classList.add(`is-scene-role-suit-${roleSuit.toLowerCase()}`);
      return;
    }
    const lockSuit = s?.lock?.suit || null;
    const hasLock = !!lockSuit;
    const hasReverse = !!s?.reverse;
    const hasCutField = String(s?.trick?.type || '') === 'set'
      && (Array.isArray(s?.trick?.cardsTable) ? s.trick.cardsTable : [])
        .some((card) => Number(idNum(card)) === 8);
    const hasWorldTimeStop = !!s?.battle?.effects?.enemy?.timeStop;
    const flashKind = String(kingdomTrickSceneFlashKind || '');
    let scene = '';
    if (flashKind === 'skip') scene = 'skip';
    else if (flashKind === 'cut' || hasCutField) scene = 'cut';
    else if (hasLock) scene = 'lock';
    else if (hasReverse) scene = 'back';
    else if (hasWorldTimeStop) scene = 'world';
    if (scene === 'cut') {
      ui.trick.classList.add('is-scene-cut');
      return;
    }
    if (scene === 'skip') {
      ui.trick.classList.add('is-scene-skip');
      return;
    }
    if (scene === 'world') {
      ui.trick.classList.add('is-scene-world');
      return;
    }
    if (scene === 'lock') {
      ui.trick.classList.add('is-scene-lock');
      const key = String(lockSuit || '').toLowerCase();
      if (['wand', 'cup', 'sword', 'pentacle'].includes(key)) {
        ui.trick.classList.add(`is-scene-lock-${key}`);
      }
      return;
    }
    if (scene === 'back') {
      ui.trick.classList.add('is-scene-back');
    }
  } finally {
    syncKingdomFieldSceneFade();
  }
}

function getKingdomChipRanking() {
  if (!s?.players || !Array.isArray(s.players)) return [];
  const rows = s.players.map((player, index) => ({
    index,
    name: String(player?.name || `P${index + 1}`),
    chips: Math.max(0, Number(player?.chips) || 0)
  }));
  rows.sort((a, b) => {
    if (b.chips !== a.chips) return b.chips - a.chips;
    return a.index - b.index;
  });
  return rows.map((row, i) => ({
    ...row,
    rank: i + 1,
    medal: KINGDOM_RANK_MEDAL[i + 1] || ''
  }));
}

function isMobileKingdomViewport() {
  if (typeof window === 'undefined') return false;
  if (!window.matchMedia) return window.innerWidth <= KINGDOM_MOBILE_BREAKPOINT;
  return window.matchMedia(`(max-width: ${KINGDOM_MOBILE_BREAKPOINT}px)`).matches;
}

function getVisibleBottomNavHeight() {
  if (typeof window === 'undefined' || typeof document === 'undefined') return 0;
  const nav = document.getElementById('bottomNav');
  if (!nav) return 0;
  const style = window.getComputedStyle(nav);
  if (style.display === 'none' || style.visibility === 'hidden' || style.pointerEvents === 'none') return 0;
  const rect = nav.getBoundingClientRect();
  return Math.max(0, Math.round(rect.height || 0));
}

function setKingdomFullscreen(active) {
  if (typeof document === 'undefined' || !document.body) return;
  document.body.classList.toggle(KINGDOM_FULLSCREEN_CLASS, active === true);
  if (!active) {
    ui.root?.style.removeProperty('--tarot-kingdom-mobile-height');
  }
  queueSyncKingdomViewportHeight();
}

function syncKingdomViewportHeight() {
  if (typeof window === 'undefined' || !ui.root) return;
  const root = ui.root;
  const rootStyle = window.getComputedStyle(root);
  if (rootStyle.display === 'none') return;
  if (!isMobileKingdomViewport()) {
    root.style.removeProperty('--tarot-kingdom-mobile-height');
    return;
  }
  const viewportHeight = Math.max(
    0,
    Number(window.visualViewport?.height) || 0,
    Number(window.innerHeight) || 0
  );
  if (!viewportHeight) return;
  const rootTop = Number(root.getBoundingClientRect().top) || 0;
  const navHeight = getVisibleBottomNavHeight();
  const available = Math.floor(viewportHeight - rootTop - navHeight - KINGDOM_MOBILE_BOTTOM_GAP);
  if (available <= 0) return;
  root.style.setProperty(
    '--tarot-kingdom-mobile-height',
    `${Math.max(KINGDOM_MOBILE_MIN_HEIGHT, available)}px`
  );
}

function queueSyncKingdomViewportHeight() {
  if (kingdomViewportSyncQueued) return;
  kingdomViewportSyncQueued = true;
  requestAnimationFrame(() => {
    kingdomViewportSyncQueued = false;
    syncKingdomViewportHeight();
  });
}

function bindKingdomViewportWatch() {
  if (kingdomViewportWatchBound || typeof window === 'undefined') return;
  const onViewportChange = () => {
    queueSyncKingdomViewportHeight();
  };
  window.addEventListener('resize', onViewportChange, { passive: true });
  window.addEventListener('orientationchange', onViewportChange, { passive: true });
  if (window.visualViewport) {
    window.visualViewport.addEventListener('resize', onViewportChange, { passive: true });
    window.visualViewport.addEventListener('scroll', onViewportChange, { passive: true });
  }
  kingdomViewportWatchBound = true;
}

function traceKingdomFlow(step, details = '') {
  if (!KINGDOM_TRACE_ENABLED) return;
  const flowId = s ? Number(s._traceFlowId || 0) : 0;
  const phase = s?.phase ?? 'no-state';
  const turn = s?.turn ?? '-';
  const trick = s?.trick ? `${s.trick.type}:${s.trick.owner}:${s.trick.count ?? '-'}` : 'null';
  const pendingDraw = s?.pendingDraw ?? '-';
  const pendingJudgment = s?.pendingJudgment ?? '-';
  const leadOwner = s?.leadRequiredOwner ?? '-';
  const suffix = details ? ` | ${details}` : '';
  const line = `[TK-TRACE#${flowId}] ${step} | phase=${phase} turn=${turn} trick=${trick} pd=${pendingDraw} pj=${pendingJudgment} lead=${leadOwner}${suffix}`;
  try {
    console.debug(line);
  } catch (_) {
    // no-op
  }
}

const clearNpcTimer = () => {
  if (npcTimer) {
    clearTimeout(npcTimer);
    npcTimer = null;
  }
  npcScheduleToken += 1;
};

const scheduleNpcTimer = (delayMs, fn) => {
  clearNpcTimer();
  const token = npcScheduleToken;
  npcTimer = setTimeout(() => {
    if (token !== npcScheduleToken) return;
    npcTimer = null;
    fn?.();
  }, Math.max(0, Number(delayMs) || 0));
};

const getNpcActionDelayMs = (phase = 'turn') => {
  // NPCの思考待機。展開が速すぎるため、フェーズごとに最低待機を持たせる。
  const phaseKey = String(phase || 'turn');
  const baseDelayMs = (
    phaseKey === 'draw' || phaseKey === 'judgment'
      ? 520
      : 640
  );
  const hasActiveCinematic = !!(
    callCinematicTimer ||
    roundStartCinematicTimer ||
    roundOutCinematicTimer ||
    openingDealStartTimer ||
    openingDealFlipTimer ||
    openingDealNextTimer ||
    trickSwapTimer
  );
  return hasActiveCinematic ? (baseDelayMs + 220) : baseDelayMs;
};

