const getMajorAttackFxFromCards = (cards) => {
  if (!Array.isArray(cards)) return null;
  const major = cards.find((card) => card?.kind === 'major');
  if (!major) return null;
  const n = Number(major.number);
  if (!Number.isFinite(n)) return null;
  const cfg = MAJOR_ATTACK_FX[n];
  if (!cfg) return null;
  return {
    number: n,
    leadEmoji: String(cfg.leadEmoji || ''),
    markerEmoji: String(cfg.markerEmoji || ''),
    pattern: String(cfg.pattern || 'burst'),
    kind: String(cfg.kind || 'normal'),
    heroDurationMs: Math.max(420, Number(cfg.heroDurationMs) || 760)
  };
};
const isMajorAttackFx = (arcanaFx) => !!(arcanaFx && Number.isFinite(Number(arcanaFx.number)));
const ARCANA_DEFEAT_PATTERNS = ['orbit', 'float', 'slam', 'burst', 'rush', 'trickster', 'throne', 'edict', 'sanctum', 'halo', 'verdict', 'rift', 'world'];
const DEFEAT_MARKER_BY_KIND = {
  slash: '🗡️',
  rock: '🏅',
  water: '💦',
  fire: '🔥'
};
const getArcanaDefeatPatternClass = (arcanaFx) => {
  const pattern = String(arcanaFx?.pattern || '').trim();
  if (!pattern || !ARCANA_DEFEAT_PATTERNS.includes(pattern)) return '';
  return `is-defeat-arcana-${pattern}`;
};
const clearArcanaDefeatPatternClasses = (node) => {
  if (!node?.classList) return;
  ARCANA_DEFEAT_PATTERNS.forEach((pattern) => node.classList.remove(`is-defeat-arcana-${pattern}`));
};
const getDefeatMarkerEmoji = (defeatKind, arcanaFx) => {
  if (String(defeatKind || '') === 'arcana') {
    return String(arcanaFx?.markerEmoji || '').trim();
  }
  return String(DEFEAT_MARKER_BY_KIND[String(defeatKind || '')] || '').trim();
};
const isMinorCourtOrAceCard = (card) => {
  if (!card || card.kind !== 'minor') return false;
  const n = Number(card.number) || 0;
  return n === 1 || (n >= 11 && n <= 14);
};
const hasMinorCourtOrAce = (cards) => Array.isArray(cards) && cards.some(isMinorCourtOrAceCard);
const hasNamedRoleDisplay = (play) => {
  if (String(play?.type || '') !== 'role') return false;
  const keyName = getRoleKeyCardName(play?.role, play?.cardsHand || []);
  return !!String(keyName || '').trim();
};
const getAttackKeyCardFromPlay = (play) => {
  if (!play) return null;
  const cards = (Array.isArray(play?.cardsTable) && play.cardsTable.length > 0)
    ? play.cardsTable
    : (Array.isArray(play?.cardsHand) ? play.cardsHand : []);
  if (!cards.length) return null;
  if (String(play?.type || '') === 'role') {
    return getRoleKeyCard(play?.role, cards) || cards[0] || null;
  }
  return cards[0] || null;
};
const pickTrickDefeatFx = (play, prevTrick) => {
  const prevCards = Array.isArray(prevTrick?.cardsTable) ? prevTrick.cardsTable : [];
  if (!play || !prevCards.length) return null;
  const info = { kind: 'normal', special: false };
  const playType = String(play?.type || '');
  const prevType = String(prevTrick?.type || '');
  const playCards = Array.isArray(play?.cardsTable) ? play.cardsTable : [];
  const attackCard = getAttackKeyCardFromPlay(play);
  const majorFx = getMajorAttackFxFromCards(attackCard ? [attackCard] : playCards);
  if (playType === 'set' && prevType === 'set') {
    if (!hasMinorCourtOrAce(playCards) && !majorFx) return info;
  } else if (playType === 'role' && prevType === 'role') {
    if (!hasNamedRoleDisplay(play) && !majorFx) return info;
  } else {
    return info;
  }
  info.special = true;
  if (majorFx) {
    info.kind = 'arcana';
    info.arcana = majorFx;
  } else {
    // Court/A based special attacks are suit-only; do not emit arcana lead emoji.
    info.arcana = null;
    const suit = getPrimarySuitFromPlay(play);
    if (suit === 'Sword') info.kind = 'slash';
    else if (suit === 'Pentacle') info.kind = 'rock';
    else if (suit === 'Cup') info.kind = 'water';
    else if (suit === 'Wand') info.kind = 'fire';
  }
  return info;
};
const suitTierForCard = (c, suit) => {
  const base = SUIT_TIER[suit] || 0;
  // 大アルカナは同数時に小アルカナより上位。スート間の勝敗は循環相性で判定する。
  if (c?.kind === 'major') return 10 + base;
  return base;
};
const mkMinor = () => { const d = []; let id = 0; SUITS.forEach((suit) => { for (let n = 1; n <= 14; n += 1) d.push({ id: `tk_m_${++id}`, kind: 'minor', suit, number: n }); }); return d; };
const mkMajor = () => Array.from({ length: 22 }, (_, n) => ({ id: `tk_a_${n}`, kind: 'major', suit: 'None', number: n }));
const mkDrawDeck = () => [...mkMinor(), ...mkMajor()];

function getKingdomTutorialLesson(state = s) {
  const stageNo = Number(state?.stage?.stageNo || 0);
  if (state?.tutorialEnabled !== true || stageNo !== 1 || state?.raid) return 0;
  return Math.max(1, Math.min(TOTAL_HANDS, Math.floor(Number(state?.handNo) || 0) + 1));
}

function getKingdomTutorialProgress(state = s) {
  const lesson = getKingdomTutorialLesson(state);
  const progress = state?.tutorialProgress;
  if (!lesson || !progress || Number(progress.lesson) !== lesson) return null;
  return progress;
}

function isKingdomTutorialParticipant(playerIndex, state = s) {
  const index = Number(playerIndex);
  return Number.isInteger(index)
    && index >= 0
    && index < Number(state?.players?.length || 0)
    && state.players[index]?.isNpc !== true;
}

function isKingdomTutorialObjectivePending(playerIndex, state = s) {
  const progress = getKingdomTutorialProgress(state);
  if (!progress || !isKingdomTutorialParticipant(playerIndex, state)) return false;
  return progress.completedPlayers?.[Number(playerIndex)] !== true;
}

function getKingdomTutorialStep(playerIndex, state = s) {
  const progress = getKingdomTutorialProgress(state);
  const index = Number(playerIndex);
  if (!progress || !Number.isInteger(index) || index < 0) return 0;
  return Math.max(0, Math.floor(Number(progress.stepsByPlayer?.[index]) || 0));
}

function getKingdomTutorialMatchupPair(playerIndex, state = s) {
  const progress = getKingdomTutorialProgress(state);
  const index = Number(playerIndex);
  if (!progress || !Number.isInteger(index) || index < 0) return null;
  const pair = progress.matchupPairs?.[index];
  if (!pair || typeof pair !== 'object') return null;
  return {
    leadCardId: String(pair.leadCardId || ''),
    replyCardId: String(pair.replyCardId || ''),
    replyBaseCard: pair.replyBaseCard && typeof pair.replyBaseCard === 'object'
      ? cloneKingdomSnapshotValue(pair.replyBaseCard, null)
      : null
  };
}

function getKingdomTutorialPrompt(state = s, playerIndex = null) {
  if (playerIndex != null && !isKingdomTutorialObjectivePending(playerIndex, state)) return '';
  switch (getKingdomTutorialLesson(state)) {
    case 1:
      return playerIndex != null && getKingdomTutorialStep(playerIndex, state) >= 1
        ? `同じ数字は　勝ちスートで返せる\n${SUIT_ADVANTAGE_LABEL}`
        : '1-1　カードで攻撃\n場より大きい数字を1枚出そう';
    case 2: return '1-2　5を2枚出して2人スキップ';
    case 3: return '1-3　ポーカー役：2～6でストレート';
    case 4: return '1-4　コール：場札＋4枚でフルハウス';
    default: return '';
  }
}

function getKingdomTutorialPlayGateViolation(play, mode, state = s) {
  const lesson = getKingdomTutorialLesson(state);
  if (!lesson || String(play?.type || '') !== 'role') return null;
  const isCall = mode === 'call' || play?.call === true;
  if (isCall && lesson < 4) return 'コールは1-4で解禁されます。';
  if (!isCall && lesson < 3) return '5枚役は1-3で解禁されます。';
  return null;
}

function isKingdomTutorialObjectivePlay(playerIndex, play, state = s) {
  if (!isKingdomTutorialObjectivePending(playerIndex, state)) return true;
  const lesson = getKingdomTutorialLesson(state);
  const isSet = play?.type === 'set';
  const isRole = play?.type === 'role';
  const isCall = isRole && play?.call === true;
  const count = Math.max(
    0,
    Number(play?.count) || Number(play?.cardsHand?.length) || Number(play?.selectedIds?.length) || 0
  );
  if (lesson === 1) {
    if (!isSet || count !== 1) return false;
    const pair = getKingdomTutorialMatchupPair(playerIndex, state);
    const selectedCardId = String(play?.selectedIds?.[0] || play?.cardsHand?.[0]?.id || '');
    const targetCardId = getKingdomTutorialStep(playerIndex, state) >= 1
      ? pair?.replyCardId
      : pair?.leadCardId;
    return !targetCardId || selectedCardId === targetCardId;
  }
  if (lesson === 2) {
    const number = Number(play?.number || play?.cardsHand?.[0]?.number || 0);
    return isSet && count === 2 && [5, 8, 11, 14].includes(number);
  }
  if (lesson === 3) return isRole && !isCall && count === 5;
  if (lesson === 4) return isCall && count === 5;
  return true;
}

function isKingdomTutorialSelectionReady(playerIndex, selectedIndexes) {
  if (!isKingdomTutorialObjectivePending(playerIndex)) return true;
  const { built, mode } = buildKingdomSelectionPlay(playerIndex, selectedIndexes);
  if (!built?.ok || !validatePlay(built.play, mode)?.ok) return false;
  return isKingdomTutorialObjectivePlay(playerIndex, built.play);
}

function getKingdomTutorialSuccessLabel(play) {
  const lesson = getKingdomTutorialLesson();
  if (lesson === 1) return getKingdomTutorialStep(play?.owner) >= 1 ? 'SUIT MATCH' : 'ATTACK';
  if (lesson === 2) {
    const number = Number(play?.number || play?.cardsHand?.[0]?.number || 0);
    if (number === 5) return '5 SKIP';
    if (number === 8) return '8 CUT';
    if (number === 11) return '11 REVERSE';
    if (number === 14) return 'ROYAL LOCK';
    return '2枚出し！';
  }
  if (lesson === 4) return 'CALL';
  return '';
}

function completeKingdomTutorialObjective(playerIndex) {
  const progress = getKingdomTutorialProgress();
  const index = Number(playerIndex);
  if (!progress || !Number.isInteger(index) || index < 0 || index >= s.players.length) return false;
  if (!Array.isArray(progress.completedPlayers)) {
    progress.completedPlayers = s.players.map(() => false);
  }
  if (!Array.isArray(progress.stepsByPlayer)) {
    progress.stepsByPlayer = s.players.map(() => 0);
  }
  if (Number(progress.lesson) === 1 && getKingdomTutorialStep(index) <= 0) {
    progress.stepsByPlayer[index] = 1;
    return 'advanced';
  }
  if (progress.completedPlayers[index] === true) return 'unchanged';
  progress.completedPlayers[index] = true;
  return 'completed';
}

function prepareKingdomTutorialSuitReply(playerIndex) {
  if (getKingdomTutorialLesson() !== 1 || getKingdomTutorialStep(playerIndex) < 1) return false;
  const pair = getKingdomTutorialMatchupPair(playerIndex);
  const baseCard = pair?.replyBaseCard;
  if (!baseCard) return false;
  if (usesDeferredKingdomGrave()) queueKingdomTrickForGrave(s.trick);
  const playerCount = getKingdomPlayerCount();
  const baseOwner = playerCount > 1
    ? (Number(playerIndex) - 1 + playerCount) % playerCount
    : Number(playerIndex);
  const number = Number(idNum(baseCard));
  const play = {
    type: 'set',
    owner: baseOwner,
    count: 1,
    selected: [],
    selectedIds: [],
    cardsHand: [{ ...baseCard }],
    cardsTable: [{ ...baseCard }],
    tableOwners: [baseOwner],
    number,
    setPower: setPowerForCards(number, [baseCard]),
    suitMask: suitMaskForCards([baseCard]),
    suitTier: Math.max(...suitsForCard(baseCard, false).map((suit) => suitTierForCard(baseCard, suit)))
  };
  s.trick = play;
  s.lastPlay = play;
  s.trickActionHistory = [];
  s.lastTurnAction = { type: 'play', playerIndex: baseOwner };
  s.trickForcedCount = 0;
  s.callOnly = false;
  s.leadRequiredOwner = null;
  s.pass = s.players.map(() => false);
  s.fold = s.players.map(() => false);
  resetKingdomNpcPassCounts();
  s.trickTransitionKind = 'normal';
  s.trickDefeatFx = null;
  log(`${pName(baseOwner)}: 相性スート練習札 ${getCardNameLabel(baseCard)}`);
  return true;
}

function buildKingdomTutorialDeck(lesson, playerCount, initialHandSize, dealerIndex = 0) {
  const safeLesson = Math.max(1, Math.min(TOTAL_HANDS, Math.floor(Number(lesson) || 1)));
  const safePlayerCount = Math.max(3, Math.min(4, Math.floor(Number(playerCount) || 4)));
  const safeHandSize = Math.max(1, Math.min(8, Math.floor(Number(initialHandSize) || 8)));
  const pool = mkMinor();
  const hands = Array.from({ length: safePlayerCount }, () => []);
  const matchupPairs = Array.from({ length: safePlayerCount }, () => null);
  const take = (suit, number) => {
    const index = pool.findIndex((card) => card.suit === suit && Number(card.number) === Number(number));
    return index >= 0 ? pool.splice(index, 1)[0] : null;
  };
  const give = (seat, suit, number) => {
    const card = take(suit, number);
    if (card && hands[seat]) hands[seat].push(card);
  };
  let opening = null;

  if (safeLesson === 1) {
    opening = take('Cup', 3);
    const lessons = [
      [['Cup', 4], ['Wand', 6], ['Cup', 6]],
      [['Sword', 7], ['Sword', 8], ['Pentacle', 8]],
      [['Cup', 9], ['Wand', 10], ['Cup', 10]],
      [['Sword', 11], ['Sword', 12], ['Pentacle', 12]]
    ];
    hands.forEach((hand, seat) => {
      const [leadSpec, replyBaseSpec, replySpec] = lessons[seat];
      const leadCard = take(...leadSpec);
      const replyBaseCard = take(...replyBaseSpec);
      const replyCard = take(...replySpec);
      if (leadCard) hand.push(leadCard);
      if (replyCard) hand.push(replyCard);
      matchupPairs[seat] = {
        leadCardId: String(leadCard?.id || ''),
        replyCardId: String(replyCard?.id || ''),
        replyBaseCard: replyBaseCard ? { ...replyBaseCard } : null
      };
    });
  } else if (safeLesson === 2) {
    const pairs = [
      [['Cup', 5], ['Wand', 5]],
      [['Sword', 8], ['Pentacle', 8]],
      [['Cup', 11], ['Wand', 11]],
      [['Sword', 14], ['Pentacle', 14]]
    ];
    hands.forEach((_hand, seat) => pairs[seat].forEach(([suit, number]) => give(seat, suit, number)));
  } else if (safeLesson === 3) {
    const suits = ['Cup', 'Wand', 'Sword', 'Pentacle'];
    hands.forEach((_hand, seat) => {
      for (let offset = 0; offset < 5; offset += 1) {
        give(seat, suits[(seat + offset) % suits.length], 2 + offset);
      }
    });
  } else {
    opening = take('Cup', 5);
    [['Wand', 5], ['Sword', 5], ['Cup', 8], ['Wand', 8]]
      .forEach(([suit, number]) => give(0, suit, number));
    [['Cup', 6], ['Wand', 6], ['Sword', 6], ['Pentacle', 6]]
      .forEach(([suit, number]) => give(1, suit, number));
    [['Cup', 7], ['Wand', 7], ['Sword', 7], ['Pentacle', 7]]
      .forEach(([suit, number]) => give(2, suit, number));
    if (safePlayerCount >= 4) {
      [['Cup', 9], ['Wand', 9], ['Sword', 9], ['Pentacle', 9]]
        .forEach(([suit, number]) => give(3, suit, number));
    }
    [['Pentacle', 1], ['Sword', 10], ['Cup', 12], ['Wand', 14]]
      .forEach(([suit, number]) => give(0, suit, number));
  }

  if (!opening) opening = take('Pentacle', 1);
  const reservedPool = safeLesson === 4
    ? pool.filter((card) => Number(card.number) === 5)
    : [];
  const fillerPool = shuf(safeLesson === 4
    ? pool.filter((card) => Number(card.number) !== 5)
    : pool);
  hands.forEach((hand) => {
    while (hand.length < safeHandSize && fillerPool.length > 0) hand.push(fillerPool.shift());
  });
  const dealOrder = [];
  for (let round = 0; round < safeHandSize; round += 1) {
    for (let offset = 0; offset < safePlayerCount; offset += 1) {
      const seat = (dealerIndex + offset) % safePlayerCount;
      if (hands[seat]?.[round]) dealOrder.push(hands[seat][round]);
    }
  }
  return {
    drawDeck: [...reservedPool, ...fillerPool, ...(opening ? [opening] : []), ...dealOrder.slice().reverse()],
    skipOpening: ![1, 4].includes(safeLesson) || !opening,
    clearOpening: false,
    openingOwner: [1, 4].includes(safeLesson) ? safePlayerCount - 1 : 0,
    matchupPairs
  };
}
const log = (m) => { s.logs.push(m); if (s.logs.length > 120) s.logs.splice(0, s.logs.length - 120); };

function toRomanNumber(value) {
  let number = Math.floor(Number(value) || 0);
  if (!Number.isFinite(number) || number <= 0) return '0';
  const romanMap = [
    [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
    [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
    [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
  ];
  let result = '';
  for (const [unit, symbol] of romanMap) {
    while (number >= unit) {
      result += symbol;
      number -= unit;
    }
  }
  return result;
}

function getMinorArcanaRankLabel(number) {
  const n = Number(number) || 0;
  if (n === 1) return 'Ace';
  if (n === 11) return 'Page';
  if (n === 12) return 'Knight';
  if (n === 13) return 'Queen';
  if (n === 14) return 'King';
  return toRomanNumber(n);
}

function getCardNameLabel(card) {
  if (!card) return '';
  if (card.kind === 'major') return ARCANA_NAME[card.number] || 'アルカナ';
  return getMinorArcanaRankLabel(card.number);
}

function getCardNumberLabel(card) {
  if (!card) return '';
  if (card.displayNumberLabelOverride != null) {
    const overrideLabel = String(card.displayNumberLabelOverride || '').trim();
    if (overrideLabel) return overrideLabel;
  }
  const options = getCardDisplayNumberOptions(card);
  if (!Array.isArray(options) || options.length <= 0) return '';
  if (options.length === 1) {
    const n = Number(options[0]) || 0;
    if (card.kind !== 'major' && n === 1) return 'A';
    return String(n);
  }
  const lo = Number(options[0]) || 0;
  const hi = Number(options[options.length - 1]) || 0;
  return `${lo}/${hi}`;
}

function getCardDisplayNumberOptions(card) {
  if (!card) return [];
  if (card.displayNumberOverride != null) {
    const overrideValue = Number(card.displayNumberOverride) || 0;
    return overrideValue > 0 ? [overrideValue] : [];
  }
  const n = Number(card.number) || 0;
  if (card.kind !== 'major') return [n];
  return [n];
}

function shouldRollCardNumber(card) {
  if (!card || card.kind !== 'major') return false;
  if (card.displayNumberLabelOverride != null) {
    const label = String(card.displayNumberLabelOverride || '').trim();
    if (label) return true;
  }
  if (card.displayNumberOverride != null) {
    const shown = Number(card.displayNumberOverride) || 0;
    const base = Number(card.number) || 0;
    return shown > 0 && shown !== base;
  }
  return false;
}

function isRomanOnlyLabel(text) {
  const s = String(text || '').trim();
  return !!s && /^[IVXLCDM]+$/i.test(s);
}

function getRoleBaseLabel(role) {
  if (!role) return '役出し';
  return ROLE_LABEL[role.key] || role.label || '役出し';
}

function getRoleKeyCard(role, cards) {
  if (!role || !Array.isArray(cards) || !cards.length) return null;
  const baseCards = cards.filter(Boolean);
  if (!baseCards.length) return null;
  const bestSuitTier = (card) => {
    const suits = suitsForCard(card, false).filter((suit) => suit && suit !== 'None');
    if (!suits.length) return 0;
    const tier = suits.reduce((max, suit) => Math.max(max, SUIT_TIER[suit] || 0), 0);
    return card?.kind === 'major' ? 10 + tier : tier;
  };
  const majorCards = baseCards.filter((card) => card?.kind === 'major');
  let candidates = majorCards.length
    ? majorCards.slice()
    : [];
  if (!candidates.length) {
    const target = Number(role?.primary?.[0] || 0);
    candidates = target > 0
      ? baseCards.filter((card) => cStrength(card) === target)
      : [];
  }
  if (!candidates.length) candidates = baseCards.slice();
  candidates.sort((a, b) => {
    const strengthDiff = cStrength(b) - cStrength(a);
    if (strengthDiff !== 0) return strengthDiff;
    return bestSuitTier(b) - bestSuitTier(a);
  });
  return candidates[0] || null;
}

function getRoleKeyCardName(role, cards) {
  const keyCard = getRoleKeyCard(role, cards);
  if (!keyCard) return '';
  const name = getCardNameLabel(keyCard);
  if (!name || isRomanOnlyLabel(name)) return '';
  return name;
}

function getRoleDisplayLabel(play) {
  const base = getRoleBaseLabel(play?.role);
  if (play?.call) return `コール${base}`;
  const keyName = getRoleKeyCardName(play?.role, play?.cardsHand || []);
  return keyName ? `${keyName}${base}` : base;
}

function getKingdomCardEffectDescription(card) {
  if (!card) return '';
  const n = Number(card.number || 0);
  if (card.kind === 'major') {
    const usesMajorGateRules = areKingdomMajorArcanaGateRulesEnabled();
    const usesMajorSpecialRules = areKingdomMajorArcanaSpecialRulesEnabled();
    const majorEffectMap = {
      0: '5枚役のみ数値ワイルド（フラッシュ化なし）',
      1: 'オールスート / 数値1固定',
      5: usesMajorSpecialRules ? '次の2人をスキップ' : '5スキップ',
      8: '8カット',
      11: '11バック',
      14: 'ロイヤルロック解除',
      15: usesMajorSpecialRules ? 'コート専用 / 11バック無視' : '',
      16: usesMajorGateRules
        ? (usesMajorSpecialRules ? '同スート場専用 / 初手不可' : 'ソード場限定（上がり不可）')
        : '単騎時はソード14扱い',
      17: usesMajorGateRules
        ? (usesMajorSpecialRules ? '同スート場専用 / 初手不可' : 'カップ場限定（上がり不可）')
        : '単騎時はカップ14扱い',
      18: usesMajorGateRules
        ? (usesMajorSpecialRules ? '同スート場専用 / 初手不可' : 'ペンタクル場限定（上がり不可）')
        : '単騎時はペンタクル14扱い',
      19: usesMajorGateRules
        ? (usesMajorSpecialRules ? '同スート場専用 / 初手不可' : 'ワンド場限定（上がり不可）')
        : '単騎時はワンド14扱い',
      20: usesMajorSpecialRules
        ? '11バック / 墓地回収'
        : '11バック / この場を流した人が墓地から小アルカナ1枚回収',
      21: usesMajorSpecialRules ? '大アルカナ1枚に返して即クリア（11バック中不可）' : '単騎でどんな場札にも返せる'
    };
    return majorEffectMap[n] || '';
  }
  if (n === 1) return '通常時15 / 大アルカナでは返せない';
  if (n === 5) return '5スキップ';
  if (n === 8) return '8カット';
  if (n === 11) return '11バック';
  if (isRoyalLockMinorCard(card)) return '場と同スートでロイヤルロック';
  return '';
}

function clearLocalInfoMessage(renderNow = false) {
  if (kingdomLocalInfoTimer) {
    clearTimeout(kingdomLocalInfoTimer);
    kingdomLocalInfoTimer = null;
  }
  if (!kingdomLocalInfoMessage) return;
  kingdomLocalInfoMessage = '';
  if (renderNow && s) renderSummary();
}

function setLocalInfoMessage(text, holdMs = 1800) {
  if (kingdomLocalInfoTimer) {
    clearTimeout(kingdomLocalInfoTimer);
    kingdomLocalInfoTimer = null;
  }
  kingdomLocalInfoMessage = String(text || '').trim();
  if (s) renderSummary();
  if (!kingdomLocalInfoMessage || holdMs <= 0) return;
  const current = kingdomLocalInfoMessage;
  kingdomLocalInfoTimer = setTimeout(() => {
    kingdomLocalInfoTimer = null;
    if (kingdomLocalInfoMessage !== current) return;
    kingdomLocalInfoMessage = '';
    if (s) renderSummary();
  }, holdMs);
}

function setLocalPriorityMessage(text, holdMs = 1800, kind = '') {
  if (kingdomLocalPriorityTimer) {
    clearTimeout(kingdomLocalPriorityTimer);
    kingdomLocalPriorityTimer = null;
  }
  kingdomLocalPriorityMessage = String(text || '').trim();
  kingdomLocalPriorityKind = String(kind || '').trim();
  if (s) renderSummary();
  if (!kingdomLocalPriorityMessage || holdMs <= 0) return;
  const current = kingdomLocalPriorityMessage;
  kingdomLocalPriorityTimer = setTimeout(() => {
    kingdomLocalPriorityTimer = null;
    if (kingdomLocalPriorityMessage !== current) return;
    kingdomLocalPriorityMessage = '';
    kingdomLocalPriorityKind = '';
    if (s) renderSummary();
  }, holdMs);
}

function clearKingdomLocalTurnAlert(removeNode = false) {
  if (kingdomLocalTurnAlertTimer) {
    clearTimeout(kingdomLocalTurnAlertTimer);
    kingdomLocalTurnAlertTimer = null;
  }
  const alert = typeof document !== 'undefined'
    ? document.getElementById('tarotKingdomLocalTurnAlert')
    : null;
  if (!alert) return;
  alert.classList.remove('is-show');
  if (removeNode) alert.remove();
}

function showKingdomLocalTurnAlert() {
  if (!ui.root || typeof document === 'undefined') return;
  let alert = document.getElementById('tarotKingdomLocalTurnAlert');
  if (!alert) {
    alert = document.createElement('div');
    alert.id = 'tarotKingdomLocalTurnAlert';
    alert.className = 'tarot-kingdom-local-turn-alert';
    alert.setAttribute('aria-hidden', 'true');
    ui.root.appendChild(alert);
  } else if (alert.parentElement !== ui.root) {
    ui.root.appendChild(alert);
  }
  clearKingdomLocalTurnAlert(false);
  void alert.offsetWidth;
  alert.classList.add('is-show');
  kingdomLocalTurnAlertTimer = setTimeout(() => {
    kingdomLocalTurnAlertTimer = null;
    alert?.classList.remove('is-show');
  }, 1050);
}

